import { MakeLogicType, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { teamLogic } from 'scenes/teamLogic'

import {
    errorTrackingAlertsDestroy,
    errorTrackingAlertsList,
    errorTrackingAlertsPartialUpdate,
} from '../../../../generated/api'
import { ErrorTrackingAlertApi } from '../../../../generated/api.schemas'

const projectId = (): string => String(teamLogic.values.currentProjectId)
const PAGE_SIZE = 100

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nativeAlertsLogicValues {
    alerts: ErrorTrackingAlertApi[]
    alertsLoaded: boolean
    alertsLoading: boolean
    loadError: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nativeAlertsLogicActions {
    deleteAlert: ({ alert }: { alert: ErrorTrackingAlertApi }) => {
        alert: ErrorTrackingAlertApi
    }
    deleteAlertFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    deleteAlertSuccess: (
        alerts: ErrorTrackingAlertApi[],
        payload?: {
            alert: ErrorTrackingAlertApi
        }
    ) => {
        alerts: ErrorTrackingAlertApi[]
        payload?: {
            alert: ErrorTrackingAlertApi
        }
    }
    loadAlerts: () => any
    loadAlertsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAlertsSuccess: (
        alerts: ErrorTrackingAlertApi[],
        payload?: any
    ) => {
        alerts: ErrorTrackingAlertApi[]
        payload?: any
    }
    setAlertEnabled: ({ alert, enabled }: { alert: ErrorTrackingAlertApi; enabled: boolean }) => {
        alert: ErrorTrackingAlertApi
        enabled: boolean
    }
    setAlertEnabledFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    setAlertEnabledSuccess: (
        alerts: ErrorTrackingAlertApi[],
        payload?: {
            alert: ErrorTrackingAlertApi
            enabled: boolean
        }
    ) => {
        alerts: ErrorTrackingAlertApi[]
        payload?: {
            alert: ErrorTrackingAlertApi
            enabled: boolean
        }
    }
}

export type nativeAlertsLogicType = MakeLogicType<nativeAlertsLogicValues, nativeAlertsLogicActions>

export const nativeAlertsLogic = kea<nativeAlertsLogicType>([
    path([
        'products',
        'error_tracking',
        'scenes',
        'ErrorTrackingConfigurationScene',
        'alerting',
        'native',
        'nativeAlertsLogic',
    ]),

    loaders(({ values }) => ({
        alerts: [
            [] as ErrorTrackingAlertApi[],
            {
                loadAlerts: async () => {
                    // The list is small in practice but paginated; walk every page so nothing is hidden.
                    const alerts: ErrorTrackingAlertApi[] = []
                    let offset = 0
                    for (;;) {
                        const page = await errorTrackingAlertsList(projectId(), { limit: PAGE_SIZE, offset })
                        alerts.push(...page.results)
                        offset += page.results.length
                        if (!page.next || page.results.length === 0) {
                            return alerts
                        }
                    }
                },
                setAlertEnabled: async ({ alert, enabled }: { alert: ErrorTrackingAlertApi; enabled: boolean }) => {
                    const updated = await errorTrackingAlertsPartialUpdate(projectId(), alert.id, { enabled })
                    return values.alerts.map((existing) => (existing.id === updated.id ? updated : existing))
                },
                deleteAlert: async ({ alert }: { alert: ErrorTrackingAlertApi }) => {
                    await errorTrackingAlertsDestroy(projectId(), alert.id)
                    return values.alerts.filter((existing) => existing.id !== alert.id)
                },
            },
        ],
    })),

    reducers({
        // The list is empty before the first load too; only a successful load may show "No alerts yet".
        alertsLoaded: [false, { loadAlertsSuccess: () => true }],
        loadError: [
            null as string | null,
            {
                loadAlerts: () => null,
                loadAlertsSuccess: () => null,
                // A 403 is the API's feature gate, not an outage: say so instead of a generic failure.
                loadAlertsFailure: (_, { errorObject }) =>
                    errorObject?.status === 403 ? 'Alerts are not enabled for this project.' : 'Could not load alerts.',
            },
        ],
    }),

    listeners(() => ({
        setAlertEnabledFailure: () => {
            lemonToast.error('Could not update the alert')
        },
        deleteAlertFailure: () => {
            lemonToast.error('Could not delete the alert')
        },
    })),
])
